import java.util.*;

class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> res = new ArrayList<>();
        dfs(root, 0, res);
        return res;
    }

    private void dfs(TreeNode node, int depth, List<List<Integer>> res) {
        if (node == null) return;
        // 首次到达这一层：新建列表
        if (depth == res.size()) res.add(new ArrayList<>());
        res.get(depth).add(node.val);
        // 必须先左后右，否则层内顺序会反
        dfs(node.left, depth + 1, res);
        dfs(node.right, depth + 1, res);
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> res = new ArrayList<>();
        if (root == null) return res;

        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int size = queue.size();   // 锁住本层节点数
            List<Integer> level = new ArrayList<>(size);
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            res.add(level);
        }
        return res;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> res = new ArrayList<>();
        if (root == null) return res;

        Deque<TreeNode> cur = new ArrayDeque<>();
        cur.offer(root);

        while (!cur.isEmpty()) {
            List<Integer> level = new ArrayList<>(cur.size());   // 预分配
            Deque<TreeNode> next = new ArrayDeque<>();

            while (!cur.isEmpty()) {
                TreeNode node = cur.poll();
                level.add(node.val);
                if (node.left != null) next.offer(node.left);
                if (node.right != null) next.offer(node.right);
            }

            res.add(level);
            cur = next;   // 交给下一层
        }
        return res;
    }
}
